"use client";
import { useState, useEffect } from "react";
import axios from "axios";
import Link from "next/link";
import { Edit as EditIcon, Delete as DeleteIcon, FileDownload as FileDownloadIcon } from "@mui/icons-material";
import { IconButton } from "@mui/material";
import Layout from "../components/Layout";
import DataTable from "../components/DataTableAffect";
import FileUpload from "../components/FileUpload";

export default function GestionGroupes() {
  const [data, setData] = useState({
    groupes: [],
    tuteurs: [],
    sujets: []
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [viewMode, setViewMode] = useState("table");

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      const [groupesResponse, etudiantsResponse, tuteursResponse, sujetsResponse] = await Promise.all([
        axios.get("http://localhost:5000/api/groupes"),
        axios.get("http://localhost:5000/api/etudiants"),
        axios.get("http://localhost:5000/api/tuteurs"),
        axios.get("http://localhost:5000/api/sujets"),
      ]);

      // Create a map of students by group ID
      const etudiantsMap = new Map();
      if (Array.isArray(etudiantsResponse.data)) {
        etudiantsResponse.data.forEach((etudiant) => {
          if (etudiant && etudiant.idGroupe) {
            if (!etudiantsMap.has(etudiant.idGroupe)) {
              etudiantsMap.set(etudiant.idGroupe, []);
            }
            etudiantsMap.get(etudiant.idGroupe).push(`${etudiant.nom || ""} ${etudiant.prenom || ""}`);
          }
        });
      }

      const tuteursData = Array.isArray(tuteursResponse.data) ? tuteursResponse.data : [];
      const sujetsData = Array.isArray(sujetsResponse.data) ? sujetsResponse.data : [];

      // Process groupe data with tuteur and sujet info
      const groupesData = Array.isArray(groupesResponse.data) 
        ? groupesResponse.data.map((groupe) => {
            const tuteur = tuteursData.find((t) => t.idTuteur === groupe.idTuteur);
            const sujet = sujetsData.find((s) => s.idSujet === groupe.idSujet);
            return {
              ...groupe,
              etudiants: etudiantsMap.get(groupe.idGroupe) || [],
              tuteur: tuteur || null,
              sujet: sujet || null,
              isAffected: !!(tuteur && sujet),
            };
          })
        : [];

      setData({
        groupes: groupesData,
        tuteurs: tuteursData,
        sujets: sujetsData,
      });
    } catch (error) {
      console.error("Erreur lors du chargement des données:", error);
      setError("Impossible de charger les données. Veuillez réessayer plus tard.");
    } finally {
      setLoading(false);
    }
  };

  const handleTuteurChange = (groupe, tuteurId) => {
    if (!tuteurId) return;
    const selectedTuteur = data.tuteurs.find((t) => t.idTuteur === tuteurId);
    if (!selectedTuteur) return;
    
    setData(prevData => ({
      ...prevData,
      groupes: prevData.groupes.map(g => {
        if (g.idGroupe === groupe.idGroupe) {
          return {
            ...g,
            tuteur: selectedTuteur,
            isAffected: false,
          };
        }
        return g;
      })
    }));
  };

  const handleSujetChange = (groupe, sujetId) => {
    if (!sujetId) return;
    const selectedSujet = data.sujets.find((s) => s.idSujet === parseInt(sujetId));
    if (!selectedSujet) return;
    
    setData(prevData => ({
      ...prevData,
      groupes: prevData.groupes.map(g => {
        if (g.idGroupe === groupe.idGroupe) {
          return {
            ...g,
            sujet: selectedSujet,
            isAffected: false,
          };
        }
        return g;
      })
    }));
  };

  const affecterGroupe = async () => {
    const groupesAAffecter = data.groupes.filter(
      (groupe) => groupe.tuteur && groupe.sujet && !groupe.isAffected
    );
    
    if (groupesAAffecter.length === 0) {
      alert("Veuillez sélectionner un tuteur et un sujet pour au moins un groupe non affecté.");
      return;
    }
    
    setLoading(true);
    try {
      for (const groupe of groupesAAffecter) {
        await axios.post(
          `http://localhost:5000/api/affecterSujetsAuGroupe/${groupe.idGroupe}`,
          {
            idTuteur: groupe.tuteur.idTuteur,
            idSujet: groupe.sujet.idSujet,
          }
        );
      }
      alert("Affectation réussie !");
      await fetchData();
    } catch (error) {
      console.error("Erreur détaillée:", error.response?.data || error.message);
      setError(`Erreur lors de l'affectation: ${error.response?.data?.message || "Erreur inconnue"}`);
    } finally {
      setLoading(false);
    }
  };

  const deleteGroupe = async (idGroupe) => {
    if (!window.confirm("Voulez-vous vraiment supprimer cette affectation ?")) return;
    
    setLoading(true);
    try {
      await axios.delete(`http://localhost:5000/api/supprimerAffectationsGroupe/${idGroupe}`);
      alert("Affectation supprimée avec succès");
      await fetchData();
    } catch (error) {
      console.error("Erreur lors de la suppression du groupe :", error);
      setError("Erreur lors de la suppression de l'affectation");
    } finally {
      setLoading(false);
    }
  };

  const exportData = async (format) => {
    try {
      const url = format === "excel" 
        ? "http://localhost:5000/api/excel" 
        : "http://localhost:5000/api/word";
      
      window.open(url, "_blank");
    } catch (error) {
      console.error(`Erreur lors de l'export en ${format}:`, error);
      setError(`Erreur lors de l'export en ${format}`);
    }
  };

  // Column configuration for DataTable
  const columns = [
    {
      id: 'groupe',
      header: 'Nom du Groupe et Étudiants',
      cell: (row) => (
        <div>
          <strong>{row.nomGroupe}</strong>
          <ul className="ml-4 list-disc">
            {row.etudiants.map((etudiant, index) => (
              <li key={index}>{etudiant}</li>
            ))}
          </ul>
        </div>
      )
    },
    {
      id: 'tuteur',
      header: 'Tuteur',
      cell: (row) => (
        row.isAffected ? (
          <span>{row.tuteur ? `${row.tuteur.nom} ${row.tuteur.prenom}` : "Non assigné"}</span>
        ) : (
          <select
            value={row.tuteur?.idTuteur || ""}
            onChange={(e) => handleTuteurChange(row, e.target.value)}
            className="border p-2 rounded w-full focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Sélectionner un tuteur</option>
            {data.tuteurs
              .filter(
                (tuteur) =>
                  !data.groupes.some(
                    (g) =>
                      g.idGroupe !== row.idGroupe &&
                      g.tuteur?.idTuteur === tuteur.idTuteur
                  )
              )
              .map((tuteur) => (
                <option key={tuteur.idTuteur} value={tuteur.idTuteur}>
                  {tuteur.nom} {tuteur.prenom}
                </option>
              ))}
          </select>
        )
      )
    },
    {
      id: 'sujet',
      header: 'Sujet',
      cell: (row) => (
        row.isAffected ? (
          <span>{row.sujet ? row.sujet.titre : "Non assigné"}</span>
        ) : (
          <select
            value={row.sujet?.idSujet || ""}
            onChange={(e) => handleSujetChange(row, e.target.value)}
            className="border p-2 rounded w-full focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Sélectionner un sujet</option>
            {data.sujets
              .filter((sujet) => {
                const count = data.groupes.filter(
                  (g) =>
                    g.idGroupe !== row.idGroupe &&
                    g.sujet?.idSujet === sujet.idSujet
                ).length;
                return count < 3;
              })
              .map((sujet) => (
                <option key={sujet.idSujet} value={sujet.idSujet}>
                  {sujet.titre}
                </option>
              ))}
          </select>
        )
      )
    },
    {
      id: 'actions',
      header: 'Actions',
      cell: (row) => (
        <div className="flex justify-center space-x-3">
          <Link href={`/users/editgrp/${row.idGroupe}`} passHref>
            <IconButton color="primary" title="Éditer">
              <EditIcon />
            </IconButton>
          </Link>
          <IconButton
            color="error"
            onClick={() => deleteGroupe(row.idGroupe)}
            title="Supprimer"
          >
            <DeleteIcon />
          </IconButton>
        </div>
      )
    }
  ];

  // Group card component for card view
  const GroupCard = ({ groupe }) => (
    <div className="bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300 p-6 border border-gray-200">
      <h3 className="text-xl font-semibold text-blue-600 mb-4">
        Groupe : {groupe.nomGroupe}
      </h3>

      <div className="mb-4">
        <p className="text-sm text-gray-500 font-medium">Tuteur</p>
        <p className="text-lg text-gray-800">
          {groupe.tuteur ? `${groupe.tuteur.nom} ${groupe.tuteur.prenom}` : "Non assigné"}
        </p>
      </div>

      <div className="mb-4">
        <p className="text-sm text-gray-500 font-medium">Sujet</p>
        <p className="text-lg text-gray-800">
          {groupe.sujet ? groupe.sujet.titre : "Non assigné"}
        </p>
      </div>

      <div>
        <p className="text-sm text-gray-500 font-medium">Étudiants</p>
        <ul className="mt-2 space-y-2">
          {groupe.etudiants.map((etudiant, index) => (
            <li key={index} className="text-gray-700">
              <span className="text-blue-500 mr-2">•</span>
              {etudiant}
            </li>
          ))}
        </ul>
      </div>

      {groupe.isAffected && (
        <p className="text-green-600 font-semibold mt-4">✓ Affecté</p>
      )}
    </div>
  );

  // Page actions for the Layout header
  const pageActions = (
    <div className="flex space-x-4">
      <button
        onClick={affecterGroupe}
        className="bg-blue-500 text-white px-6 py-2 rounded hover:bg-blue-600 transition-all"
        disabled={loading}
      >
        Affecter
      </button>
      <button
        onClick={() => setViewMode(viewMode === "table" ? "card" : "table")}
        className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600 transition-all"
      >
        {viewMode === "table" ? "Voir la liste" : "Voir le tableau"}
      </button>
      <div className="relative">
        <FileUpload 
          onExport={(format) => exportData(format)}
          formats={["excel", "word"]}
          buttonText="Exporter"
          buttonIcon={<FileDownloadIcon className="mr-1" />}
          className="bg-teal-500 hover:bg-teal-600"
        />
      </div>
    </div>
  );

  return (
    <Layout
      title="Affectation des Groupes"
      loading={loading}
      error={error}
      actions={pageActions}
    >
      {viewMode === "table" ? (
        <DataTable
          data={data.groupes}
          columns={columns}
          searchable={true}
          searchPlaceholder="Rechercher un groupe..."
          className="bg-white rounded-xl shadow-lg"
          emptyMessage="Aucun groupe trouvé"
        />
      ) : (
        <div className="mt-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {data.groupes.map(groupe => (
            <GroupCard key={groupe.idGroupe} groupe={groupe} />
          ))}
        </div>
      )}
    </Layout>
  );
}