// components/FileUpload.js
'use client';

import { useState } from 'react';
import { FileUpload as UploadIcon } from '@mui/icons-material';

export default function FileUpload({ 
  onUpload, 
  accept = ".xlsx, .xls", 
  loading = false,
  title = "Import data",
  description = "Drag and drop a file or click to select"
}) {
  const [file, setFile] = useState(null);
  const [dragging, setDragging] = useState(false);
  const [message, setMessage] = useState('');

  const handleFileChange = (e) => {
    if (e.target.files?.[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setDragging(true);
  };

  const handleDragLeave = () => {
    setDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragging(false);
    if (e.dataTransfer.files?.[0]) {
      setFile(e.dataTransfer.files[0]);
    }
  };

  const handleSubmit = async () => {
    if (!file) {
      setMessage("Please select a file");
      return;
    }
    setMessage('');
    await onUpload(file);
  };

  return (
    <div className="max-w-md p-6 border rounded-xl shadow-lg bg-gradient-to-r from-white to-gray-50">
      <h1 className="text-md font-semibold mb-4 text-gray-800">{title}</h1>
      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className={`file-upload-container ${
          dragging ? 'file-upload-container-dragging' : ''
        }`}
      >
        {file ? (
          <p className="text-gray-700">{file.name}</p>
        ) : (
          <>
            <UploadIcon className="text-gray-400 text-4xl mb-2" />
            <p className="text-gray-500">{description}</p>
          </>
        )}
        <input 
          type="file" 
          accept={accept} 
          onChange={handleFileChange} 
          className="hidden" 
          id="fileInput" 
        />
        <label 
          htmlFor="fileInput" 
          className="cursor-pointer text-blue-600 hover:text-blue-700 mt-2 inline-block"
        >
          Select a file
        </label>
      </div>
      <button
        onClick={handleSubmit}
        disabled={loading || !file}
        className="btn-primary mt-4 w-full disabled:opacity-50"
      >
        {loading ? "Uploading..." : "Upload"}
      </button>
      {message && (
        <p className="mt-3 text-red-600 text-sm">{message}</p>
      )}
    </div>
  );
}